<script setup lang="ts">
import { v4 as newRequestKey } from "uuid";
import Modal from "@papilio/ui/Modal.vue";
import { useI18n } from "vue-i18n";
import { computed, onUnmounted, ref, watch } from "vue";
import { useAuth } from "@papilio/auth";
import { item, query, request, type Page, type SupportTicket, type SupportMessage, type SupportHistory, type SupportAvailability, type SupportStatus } from "@papilio/api";
import { faDate, faNumber } from "@papilio/ui";
const { t } = useI18n();
const props=defineProps<{audience:"admin"|"customer";customerId?:number;subscriptionId?:number;topupId?:number;ticketId?:number}>();const auth=useAuth();
const prefix=computed(()=>`/v1/${props.audience}/support`);const rows=ref<SupportTicket[]>([]);const q=ref("");const status=ref("");const page=ref(1);const pages=ref(1);const total=ref(0);const selected=ref<SupportTicket|null>(null);const policy=ref<SupportAvailability|null>(null);
const loading=ref(false);const selecting=ref(false);const busy=ref(false);const error=ref("");const notice=ref("");const messages=ref<SupportMessage[]>([]);const history=ref<SupportHistory[]>([]);const messagePage=ref(1);const messagePages=ref(1);const historyPage=ref(1);const historyPages=ref(1);const threadLoading=ref(false);const threadError=ref("");
const subject=ref("");const body=ref("");const replyBody=ref("");const reason=ref("");const nextStatus=ref<SupportStatus>("closed");const createKey=ref(newRequestKey());const replyKey=ref(newRequestKey());let listVersion=0;let selectionVersion=0;let threadVersion=0;
const labels:Record<SupportStatus,string>={open:t("supportWorkspace.pendingSupport"),waiting_customer:t("supportWorkspace.pendingCustomer"),closed:t("supportWorkspace.closed")};
const createOpen=ref(false),draftCustomer=ref<number|undefined>();
function startCreate():void{if(busy.value||selecting.value||!mayCreate.value)return;if(draftCustomer.value===undefined)draftCustomer.value=creationCustomer.value;createOpen.value=true;}
const creationCustomer=computed(()=>props.customerId??selected.value?.customer_id);
const mayCreate=computed(()=>policy.value?.capacity_valid&&policy.value.new_tickets_enabled&&(props.audience==="customer"||auth.can("support","create")&&creationCustomer.value!==undefined));
const mayReply=computed(()=>policy.value?.capacity_valid&&(props.audience==="customer"?policy.value.customer_replies_enabled:auth.can("support","update")&&policy.value.staff_replies_enabled)&&(selected.value?.status!=="closed"||policy.value.closed_reply_mode==="reopen"));
const mayChange=computed(()=>props.audience==="admin"?auth.can("support","update"):Boolean(selected.value?.status==="closed"?policy.value?.customer_reopen_enabled:policy.value?.customer_closure_enabled));
function characterCount(value:string):number{return Array.from(value).length;}
function validMessage(value:string):boolean{return Boolean(policy.value&&characterCount(value)<=policy.value.max_message_chars);}
function fail(cause:unknown):string{return cause instanceof Error?cause.message:"The operation failed. Please try again.";}
async function load():Promise<void>{const version=++listVersion;loading.value=true;error.value="";try{const [result,settings]=await Promise.all([request<Page<SupportTicket>>(`${prefix.value}?${query({q:q.value,status:status.value||undefined,page:page.value,customer_id:props.audience==="admin"?props.customerId:undefined})}`),item<SupportAvailability>(`${prefix.value}/policy`)]);if(version!==listVersion)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;policy.value=settings;}catch(cause){if(version===listVersion)error.value=fail(cause);}finally{if(version===listVersion)loading.value=false;}}
async function loadThread():Promise<void>{const row=selected.value;if(!row)return;const version=++threadVersion;threadLoading.value=true;threadError.value="";try{const [msgs,audit]=await Promise.all([request<Page<SupportMessage>>(`${prefix.value}/${row.id}/messages?${query({page:messagePage.value})}`),request<Page<SupportHistory>>(`${prefix.value}/${row.id}/history?${query({page:historyPage.value})}`)]);if(version!==threadVersion||selected.value?.id!==row.id)return;messages.value=msgs.data;messagePages.value=msgs.meta.pager?.total_pages??1;history.value=audit.data;historyPages.value=audit.meta.pager?.total_pages??1;}catch(cause){if(version===threadVersion)threadError.value=fail(cause);}finally{if(version===threadVersion)threadLoading.value=false;}}
async function select(row:Pick<SupportTicket,"id">,preserve=false):Promise<void>{if(busy.value||selecting.value)return;const version=++selectionVersion;selecting.value=true;error.value="";try{const fresh=await item<SupportTicket>(`${prefix.value}/${row.id}`);if(version!==selectionVersion)return;selected.value=fresh;if(!preserve){replyBody.value="";reason.value="";replyKey.value=newRequestKey();nextStatus.value=fresh.status==="closed"?"open":"closed";messagePage.value=1;historyPage.value=1;messages.value=[];history.value=[];}void loadThread();if(preserve)notice.value=t("supportWorkspace.retainedDraft");}catch(cause){if(version===selectionVersion)error.value=fail(cause);}finally{if(version===selectionVersion)selecting.value=false;}}
async function create():Promise<void>{if(busy.value||selecting.value||!mayCreate.value||!validMessage(body.value)||characterCount(subject.value)>100)return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<SupportTicket>(prefix.value,"POST",{request_key:createKey.value,subject:subject.value,body:body.value,subscription_id:props.subscriptionId,topup_id:props.topupId,...(props.audience==="admin"?{customer_id:draftCustomer.value}:{})});if(stamp!==selectionVersion)return;selected.value=result;subject.value="";body.value="";createKey.value=newRequestKey();replyBody.value="";replyKey.value=newRequestKey();reason.value="";nextStatus.value=result.status==="closed"?"open":"closed";messagePage.value=1;historyPage.value=1;createOpen.value=false;draftCustomer.value=undefined;notice.value=t("supportWorkspace.ticketCreated");await load();await loadThread();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function reply():Promise<void>{const row=selected.value;if(!row||busy.value||selecting.value||!mayReply.value||!validMessage(replyBody.value))return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<SupportTicket>(`${prefix.value}/${row.id}/messages`,"POST",{request_key:replyKey.value,expected_revision:row.revision,body:replyBody.value});if(stamp!==selectionVersion)return;selected.value=result;replyBody.value="";replyKey.value=newRequestKey();notice.value=t("supportWorkspace.replyRecorded");messagePage.value=1;historyPage.value=1;await load();await loadThread();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
async function change():Promise<void>{const row=selected.value;if(!row||busy.value||selecting.value||!mayChange.value)return;const stamp=selectionVersion;busy.value=true;error.value="";notice.value="";try{const result=await item<SupportTicket>(`${prefix.value}/${row.id}/state`,"PUT",{expected_revision:row.revision,status:nextStatus.value,reason:reason.value});if(stamp!==selectionVersion)return;selected.value=result;reason.value="";notice.value=t("supportWorkspace.statusSaved");await load();await loadThread();}catch(cause){if(stamp===selectionVersion)error.value=fail(cause);}finally{busy.value=false;}}
watch([q,status],()=>{page.value=1;void load();});onUnmounted(()=>{selectionVersion++;listVersion++;threadVersion++;});
watch(()=>[props.audience,props.customerId,props.subscriptionId,props.topupId,props.ticketId],()=>{selectionVersion++;threadVersion++;selected.value=null;createOpen.value=false;draftCustomer.value=undefined;subject.value="";body.value="";page.value=1;createKey.value=newRequestKey();void load();if(props.ticketId!==undefined)void select({id:props.ticketId});},{immediate:true});
</script>
<template>
  <p v-if="error" class="message error" role="alert">{{error}}</p>
  <p v-if="notice" class="message" role="status">{{notice}}</p>
  <p v-if="policy&&!policy.capacity_valid" class="message error">{{t("supportWorkspace.policyCapacity")}}</p>
  <div :class="{split:!!selected}">
    <section class="card card-pad">
      <h2>{{t("supportWorkspace.tickets")}}</h2>
      <div class="form-grid">
        <label class="field"><span>{{t("supportWorkspace.searchSubject")}}</span><input v-model="q" maxlength="100" :disabled="busy" /></label>
        <label class="field"><span>{{t("supportWorkspace.ticketStatus")}}</span><select v-model="status" :aria-label="t('supportWorkspace.ticketStatus')" :disabled="busy"><option value="">{{t("supportWorkspace.all")}}</option><option v-for="(label,value) in labels" :key="value" :value="value">{{label}}</option></select></label>
        <button class="btn secondary" :disabled="loading||busy" @click="load">{{t("supportWorkspace.refreshTickets")}}</button>
      </div>
      <div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("supportWorkspace.subject")}}</th><th v-if="audience==='admin'">{{t("supportWorkspace.customer")}}</th><th>{{t("supportWorkspace.status")}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="{'selected-row':selected?.id===row.id}" tabindex="0" @click="select(row)" @keydown.enter="select(row)"><td>{{row.subject}} · {{faNumber(row.id)}}</td><td v-if="audience==='admin'">{{faNumber(row.customer_id)}}</td><td>{{labels[row.status]}}</td></tr></tbody></table></div>
      <p v-if="loading">{{t("supportWorkspace.loading")}}</p><p v-else-if="!rows.length&&!error">{{t("supportWorkspace.noTickets")}}</p>
      <div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} {{t("supportWorkspace.ticketsCount")}}</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div>
    </section>
    <div class="stack">
      <section v-if="selected" class="card card-pad stack">
        <h2>{{selected.subject}}</h2><p>{{labels[selected.status]}} · {{t("supportWorkspace.revision")}} {{faNumber(selected.revision)}} · {{faDate(selected.updated_at)}}</p>
        <p v-if="selected.subscription_id">{{t("supportWorkspace.relatedSubscription")}} {{faNumber(selected.subscription_id)}}</p><p v-if="selected.topup_id">{{t("supportWorkspace.relatedPayment")}} {{faNumber(selected.topup_id)}}</p>
        <p v-if="threadError" class="message error">{{threadError}}</p><p v-if="threadLoading">{{t("supportWorkspace.loadingConversation")}}</p><button class="btn secondary" :disabled="busy||selecting" @click="select(selected,true)">{{t("supportWorkspace.refreshRetain")}}</button>
        <article v-for="row in messages" :key="row.id" class="ticket-message"><strong>{{row.author_kind==='staff'?t("supportWorkspace.support"):t("supportWorkspace.customer")}} · {{faDate(row.created_at)}}</strong><p class="message-body">{{row.body}}</p><small v-if="audience==='admin'&&row.staff_id!=null">{{t("supportWorkspace.staffId")}} {{faNumber(row.staff_id)}}</small><small v-else-if="audience==='admin'&&row.customer_id!=null">{{t("supportWorkspace.customerId")}} {{faNumber(row.customer_id)}}</small></article>
        <div class="pager"><button :disabled="messagePage<=1||threadLoading" @click="messagePage--;loadThread()">‹</button><span>{{t("supportWorkspace.messages")}} · {{faNumber(messagePage)}}</span><button :disabled="messagePage>=messagePages||threadLoading" @click="messagePage++;loadThread()">›</button></div>
        <form v-if="mayReply" class="form-grid" @submit.prevent="reply"><label class="field"><span>{{t("supportWorkspace.replyMessage")}}</span><textarea :aria-label="t('supportWorkspace.replyMessage')" v-model="replyBody" required :disabled="busy||selecting" /><small>{{faNumber(characterCount(replyBody))}} / {{faNumber(policy!.max_message_chars)}}</small></label><button class="btn" :disabled="busy||selecting||!replyBody.trim()||!validMessage(replyBody)">{{t("supportWorkspace.sendReply")}}</button></form><p v-else-if="policy" class="hint-box">{{t("supportWorkspace.repliesUnavailable")}}</p>
        <form v-if="mayChange" class="form-grid" @submit.prevent="change"><label class="field"><span>{{t("supportWorkspace.newStatus")}}</span><select v-model="nextStatus" :aria-label="t('supportWorkspace.newStatus')" :disabled="busy||selecting"><option value="open" :disabled="audience==='customer'&&!policy?.customer_reopen_enabled">{{t("supportWorkspace.pendingSupport")}}</option><option v-if="audience==='admin'" value="waiting_customer">{{t("supportWorkspace.pendingCustomer")}}</option><option value="closed" :disabled="audience==='customer'&&!policy?.customer_closure_enabled">{{t("supportWorkspace.closed")}}</option></select></label><label class="field"><span>{{t("supportWorkspace.changeReason")}}</span><input v-model="reason" minlength="3" maxlength="250" required :disabled="busy||selecting" /></label><button class="btn secondary" :disabled="busy||selecting||reason.trim().length<3">{{t("supportWorkspace.saveStatus")}}</button></form>
        <details><summary>{{t("supportWorkspace.statusHistory")}}</summary><div v-for="row in history" :key="row.id" class="hint-box"><p>{{labels[row.previous_status]}} → {{labels[row.status]}} · {{faNumber(row.revision)}}</p><p>{{row.reason}} · {{row.author_kind==='staff'?t("supportWorkspace.support"):t("supportWorkspace.customer")}} · {{faDate(row.created_at)}}</p></div><div class="pager"><button :disabled="historyPage<=1||threadLoading" @click="historyPage--;loadThread()">‹</button><span>{{faNumber(historyPage)}}</span><button :disabled="historyPage>=historyPages||threadLoading" @click="historyPage++;loadThread()">›</button></div></details>
      </section>
      <button v-if="mayCreate" class="btn" :disabled="busy||selecting" @click="startCreate">+ {{t("supportWorkspace.createTicket")}}</button>
      <Modal v-if="mayCreate" v-model="createOpen" :title="t('supportWorkspace.createSupportTicket')" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="audience==='admin'">{{t("supportWorkspace.forCustomer")}} {{faNumber(draftCustomer!)}}</p><p v-if="subscriptionId">{{t("supportWorkspace.aboutSubscription")}} {{faNumber(subscriptionId)}}</p><p v-if="topupId">{{t("supportWorkspace.aboutPayment")}} {{faNumber(topupId)}}</p><form class="form-grid" @submit.prevent="create"><label class="field"><span>{{t("supportWorkspace.ticketSubject")}}</span><input v-model="subject" required :disabled="busy||selecting" /></label><label class="field"><span>{{t("supportWorkspace.message")}}</span><textarea :aria-label="t('supportWorkspace.message')" v-model="body" required :disabled="busy||selecting" /><small>{{faNumber(characterCount(body))}} / {{faNumber(policy!.max_message_chars)}}</small></label><button class="btn" :disabled="busy||selecting||!subject.trim()||characterCount(subject)>100||!body.trim()||!validMessage(body)">{{t("supportWorkspace.createTicket")}}</button></form></Modal>
      <p v-else-if="audience==='admin'&&auth.can('support','create')&&!creationCustomer" class="hint-box">{{t("supportWorkspace.selectCustomerForTicket")}}</p>
    </div>
  </div>
</template>
<style scoped>.ticket-message{padding:14px;border:1px solid var(--line);border-radius:12px;min-width:0}.message-body{white-space:pre-wrap;overflow-wrap:anywhere}.ticket-message strong{font-size:13px}textarea{min-height:130px;resize:vertical}.stack{min-width:0}</style>
